import Foundation
import XCTest
@testable import WorldsSyncWire

final class WorldsSyncWireTests: XCTestCase {
    typealias Wire = WorldsSyncWire

    func testLib0GoldenFrames() throws {
        // Fixtures generated by the repository's installed lib0 encoder.
        let cases: [(Wire.Frame, [UInt8])] = [
            (.sync(channel: 1, kind: 2, payload: Data([0, 128, 255])), [0, 1, 2, 3, 0, 128, 255]),
            (.update(batchID: 300, channel: 1, update: Data([5, 6])), [4, 172, 2, 1, 2, 5, 6]),
            (.authState(level: "edit", userID: "ع"), [3, 4, 101, 100, 105, 116, 2, 216, 185]),
            (.acknowledgement(batchID: 300, status: 2, reason: "no"), [5, 172, 2, 2, 2, 110, 111]),
            (.notice(code: "x", message: "hi"), [6, 1, 120, 2, 104, 105]),
            (.authRefresh(token: "abc"), [7, 3, 97, 98, 99]),
            (.awareness(Data([1, 2])), [1, 2, 1, 2]),
            (.queryAwareness, [2])
        ]
        for (frame, bytes) in cases {
            XCTAssertEqual(try Wire.encode(frame), Data(bytes))
            XCTAssertEqual(try Wire.decode(Data(bytes)), frame)
        }
    }

    func testAwarenessUpdateAndLargeIntegers() throws {
        let entries = [Wire.AwarenessEntry(clientID: 300, clock: 128, state: "null"),
                       Wire.AwarenessEntry(clientID: Wire.maxSafeInteger, clock: 1, state: "ع")]
        let bytes = try Wire.encodeAwarenessUpdate(entries)
        XCTAssertEqual(try Wire.decodeAwarenessUpdate(bytes), entries)
        XCTAssertEqual(Array(bytes.prefix(10)), [2, 172, 2, 128, 1, 4, 110, 117, 108, 108])
    }

    func testPermissionMatrix() {
        for channel: UInt64 in [0, 1, 2] {
            XCTAssertEqual(Wire.canWrite(.full, channel: channel), channel < 2)
            XCTAssertEqual(Wire.canWrite(.edit, channel: channel), channel < 2)
            XCTAssertEqual(Wire.canWrite(.comment, channel: channel), channel == 1)
            XCTAssertFalse(Wire.canWrite(.view, channel: channel))
            XCTAssertFalse(Wire.canWrite(.none, channel: channel))
        }
    }

    func testRejectsMalformedFrames() throws {
        XCTAssertThrowsError(try Wire.decode(Data([4, 128])))
        XCTAssertThrowsError(try Wire.decode(Data([1, 2, 1])))
        XCTAssertThrowsError(try Wire.decode(Data([7, 1, 255])))
        XCTAssertThrowsError(try Wire.decode(Data([2, 0])))
        XCTAssertThrowsError(try Wire.decode(Data([8])))
        XCTAssertThrowsError(try Wire.decodeAwarenessUpdate(Data([2, 0, 0, 0])))
        XCTAssertThrowsError(try Wire.encode(.update(batchID: Wire.maxSafeInteger + 1, channel: 0, update: Data())))
    }
}
